<script>
  // ---- simulated page-metadata lookup (a prototype fakes the external fetch) ----
  var CANNED = {
    'nytimes.com': {t:'The New York Times — Breaking News', d:'Live coverage of world news, politics, business, and culture.'},
    'wikipedia.org': {t:'Wikipedia, the free encyclopedia', d:'The free encyclopedia that anyone can edit.'},
    'seriouseats.com': {t:'Serious Eats: Recipes & Techniques', d:'Tested recipes and the science of great home cooking.'},
    'github.com': {t:'GitHub', d:'Where the world builds software.'},
    'youtube.com': {t:'YouTube', d:'Watch, share, and discover videos.'}
  };
  function domainOf(url){
    var u = url.replace(/^https?:\/\//i,'').replace(/^www\./i,'');
    return u.split('/')[0].toLowerCase();
  }
  function normalize(url){
    return url.replace(/^https?:\/\//i,'').replace(/^www\./i,'').replace(/\/+$/,'').toLowerCase();
  }
  function palette(dom){
    var colors=['#2f6fed','#e0663a','#2fa36b','#8a4fd0','#d0434f','#1f8a9c','#c78a1a'];
    var s=0; for(var i=0;i<dom.length;i++) s+=dom.charCodeAt(i);
    return colors[s%colors.length];
  }
  function faviconHTML(dom,cls){
    var letter = dom.charAt(0).toUpperCase();
    var color = palette(dom);
    // try a real favicon, fall back to a colored letter tile
    return '<span class="favicon'+(cls?' '+cls:'')+'" style="background:'+color+'">'+
      '<img src="https://www.google.com/s2/favicons?domain='+encodeURIComponent(dom)+'&sz=64" '+
      'onerror="this.style.display=\'none\'" alt="">'+
      '<span style="position:absolute">'+letter+'</span></span>';
  }
  function lookup(url){
    var dom = domainOf(url);
    var base = CANNED[dom];
    if(base) return {title:base.t, desc:base.d, dom:dom};
    var name = dom.split('.')[0];
    name = name.charAt(0).toUpperCase()+name.slice(1);
    return {title:name, desc:'A page saved from '+dom+'.', dom:dom};
  }

  var items = [];
  var usedTags = {};
  var listEl=document.getElementById('list'), countEl=document.getElementById('count');
  var urlEl=document.getElementById('url'), previewEl=document.getElementById('preview'),
      fieldsEl=document.getElementById('fields'), faviconEl=document.getElementById('favicon'),
