    // duplicate?
    var existing = items.find(function(b){return normalize(b.url)===normalize(url);});
    if(existing){
      previewEl.classList.remove('show'); fieldsEl.classList.remove('show');
      showDuplicate(existing);
      return;
    }

    previewEl.classList.add('show'); fieldsEl.classList.remove('show');
    fetchTimer = setTimeout(function(){
      var meta = lookup(url);
      currentDom = meta.dom;
      titleEl.value = meta.title; descEl.value = meta.desc;
      faviconEl.outerHTML = faviconHTML(meta.dom).replace('class="favicon','id="favicon" class="favicon');
      faviconEl = document.getElementById('favicon');
      faviconEl.style.width='38px'; faviconEl.style.height='38px'; faviconEl.style.fontSize='16px';
      previewEl.classList.remove('show'); fieldsEl.classList.add('show');
    }, 700);
  });

  function showDuplicate(b){
    dupEl.innerHTML = 'You already saved this link. <a href="#bm-'+b.id+'" style="color:inherit;font-weight:600;margin-left:4px">Go to it to update →</a>';
    dupEl.classList.add('show');
    dupEl.querySelector('a').onclick=function(e){e.preventDefault();openEditor(b.id,true);};
  }

  // ---- tag suggestions ----
  var activeSug=-1;
  tagsEl.addEventListener('input', function(){
    var val=tagsEl.value; var parts=val.split(','); var cur=parts[parts.length-1].trim().toLowerCase();
    if(!cur){ suggestEl.classList.remove('show'); return; }
    var chosen = parts.slice(0,-1).map(function(t){return t.trim().toLowerCase();});
    var matches=Object.keys(usedTags).filter(function(t){
      return t.indexOf(cur)===0 && chosen.indexOf(t)<0;
    }).slice(0,6);
    if(!matches.length){ suggestEl.classList.remove('show'); return; }
    activeSug=-1;
    suggestEl.innerHTML=matches.map(function(t){return '<div>'+esc(t)+'</div>';}).join('');
    Array.prototype.forEach.call(suggestEl.children,function(el){
      el.onclick=function(){ applyTag(parts,el.textContent); };
    });
    suggestEl.classList.add('show');
  });
  function applyTag(parts,tag){
    parts[parts.length-1]=' '+tag;
    tagsEl.value=parts.join(',')+', ';
    suggestEl.classList.remove('show'); tagsEl.focus();
  }
  tagsEl.addEventListener('keydown',function(e){
    if(!suggestEl.classList.contains('show')) return;
    var opts=suggestEl.children;
    if(e.key==='ArrowDown'){e.preventDefault();activeSug=Math.min(activeSug+1,opts.length-1);}
    else if(e.key==='ArrowUp'){e.preventDefault();activeSug=Math.max(activeSug-1,0);}
    else if(e.key==='Enter'&&activeSug>=0){e.preventDefault();opts[activeSug].click();return;}
    else return;
    Array.prototype.forEach.call(opts,function(el,i){el.classList.toggle('active',i===activeSug);});
  });
  document.addEventListener('click',function(e){
    if(!e.target.closest('.tagwrap')) suggestEl.classList.remove('show');
  });

  function parseTags(raw){
    return raw ? raw.split(',').map(function(t){return t.trim();}).filter(Boolean) : [];
  }
  function rememberTags(tags){ tags.forEach(function(t){usedTags[t.toLowerCase()]=true;}); }

  // ---- save ----
  document.getElementById('composer').addEventListener('submit',function(e){
    e.preventDefault();
    var url=urlEl.value.trim(); if(!url) return;
    var existing=items.find(function(b){return normalize(b.url)===normalize(url);});
    if(existing){ openEditor(existing.id,true); return; }
    var tags=parseTags(tagsEl.value);
    var b={id:Date.now(),url:url,title:titleEl.value.trim()||url,desc:descEl.value.trim(),
      note:noteEl.value.trim(),tags:tags,dom:currentDom||domainOf(url)};
    items.unshift(b); rememberTags(tags);
    urlEl.value='';titleEl.value='';descEl.value='';tagsEl.value='';noteEl.value='';
    fieldsEl.classList.remove('show');
    render(b.id); urlEl.focus();
  });

  // ---- inline editor on an existing bookmark ----
  function openEditor(id,scroll){
    render(null,id);
    if(scroll){var el=document.getElementById('bm-'+id);
      if(el){el.scrollIntoView({behavior:'smooth',block:'center'});
        el.classList.add('highlight');setTimeout(function(){el.classList.remove('highlight');},1600);}}
  }

  function render(justAddedId,editId){
    countEl.textContent = items.length ? items.length+(items.length===1?' bookmark':' bookmarks') : '';
    if(!items.length){
      listEl.innerHTML='<div class="empty"><div class="big">No bookmarks yet</div>'+
        'Paste a link above to save your first one.</div>'; return;
    }
    listEl.innerHTML=items.map(function(b){
      if(b.id===editId){
        return '<div class="item highlight" id="bm-'+b.id+'">'+
          '<div class="head">'+faviconHTML(b.dom)+
          '<div><div class="title">'+esc(b.title)+'</div><div class="url">'+esc(b.url)+'</div></div></div>'+
          '<div class="editor">'+
            '<label>Description</label><textarea id="e-desc">'+esc(b.desc)+'</textarea>'+
            '<label>Tags</label><input id="e-tags" value="'+esc((b.tags||[]).join(', '))+'">'+
            '<label>Note</label><textarea id="e-note">'+esc(b.note||'')+'</textarea>'+
            '<button class="save" onclick="saveEdit('+b.id+')">Update bookmark</button>'+
          '</div></div>';
      }
      var tags=(b.tags||[]).map(function(t){return '<span class="tag">'+esc(t)+'</span>';}).join('');
      return '<div class="item'+(b.id===justAddedId?' just-added':'')+'" id="bm-'+b.id+'">'+
        '<div class="head">'+faviconHTML(b.dom)+
        '<div style="flex:1"><div class="title"><a href="'+esc(b.url)+'" target="_blank" rel="noopener">'+esc(b.title)+'</a></div>'+
        '<div class="url">'+esc(b.url)+'</div></div></div>'+
        (b.desc?'<div class="desc">'+esc(b.desc)+'</div>':'')+
        (tags?'<div class="tags">'+tags+'</div>':'')+
        '<button class="edit-btn" onclick="openEditor('+b.id+',false)">Edit</button>'+
      '</div>';
    }).join('');
  }

  window.openEditor=openEditor;
  window.saveEdit=function(id){
    var b=items.find(function(x){return x.id===id;}); if(!b) return;
    b.desc=document.getElementById('e-desc').value.trim();
    b.tags=parseTags(document.getElementById('e-tags').value);
    b.note=document.getElementById('e-note').value.trim();
    rememberTags(b.tags);
    render(id);
    var el=document.getElementById('bm-'+id);
    if(el){el.classList.add('highlight');setTimeout(function(){el.classList.remove('highlight');},1600);}
  };

  render();
  document.body.setAttribute('data-harness-ready','true');
</script>
</body>
